    if (g.id === 'seed_bomb') { if (h.type !== 'block' || !BC.BLOCKS[h.id].soil) return this.toast('Toss the seed bomb onto bare soil.', ''); const biome = w.biomeAt(h.x, h.z); const opts = BC.PLANTS.filter(p => p.biomes.includes(biome) && p.pollinator && !p.invasive && p.water !== 'aquatic' && !p.epiphyte); let n = 0; const cells = []; for (let dz = -2; dz <= 2; dz++) for (let dx = -2; dx <= 2; dx++) cells.push([h.x + dx, h.z + dz]); cells.sort(() => Math.random() - 0.5); for (const [x, z] of cells) { if (n >= 3 || !opts.length) break; const t = w.top(x, z); const b = BC.BLOCKS[w.get(x, t, z)]; if (!b || !b.soil || w.get(x, t + 1, z) !== 0 || w.plantAt(x, t + 1, z)) continue; const d = opts[Math.floor(Math.random() * opts.length)]; w.addPlant({ id: d.id, x, y: t + 1, z, wild: false, progress: 0.2, health: 1, owner: this.playerName }); n++; } if (!n) return this.toast('No bare soil near there for it to take.', ''); this.take(consumed); st.planted += n; return this.toast(`The clay ball breaks and ${n} wildflower seedlings take root. Bees will find them.`, 'good'); }
